mapper.select:
SELECT count(1), min(duar.source_id) min_id, max(duar.source_id) max_id
FROM dwd_user_ad_record duar
WHERE duar.dates = #{dates}

SELECT count(1), min(omasda.id) min_id, max(omasda.id) max_id
FROM ods_max_ad_stat_detail_ads omasda
WHERE omasda.dates = #{dates}

select t.id, t.source_id, t.dates, t.gaid, t.pkg, t.ad_format, t.network, t.ad_exhibit, t.revenue, t.source_create_time, dui.user_id, dui.last_version `version`, dui.pkg, dui.country from (SELECT duar.id, omasda.id source_id, omasda.dates, omasda.gaid, omasda.pkg, omasda.ad_format, omasda.network, omasda.ad_exhibit, omasda.revenue, omasda.created source_create_time FROM ods_max_ad_stat_detail_ads omasda LEFT JOIN dwd_user_ad_record duar on (duar.source_id = omasda.id and duar.dates = omasda.dates) WHERE omasda.dates = #{dates}
and omasda.id > #{startSourceId}
order by omasda.id LIMIT #{rowNum}) t INNER JOIN dim_user_info dui on (t.gaid = dui.gaid and t.pkg = dui.pkg)
